    internal sealed class SynthesisTheoremCandidate
    {
        public string Id { get; set; }
        public string PatternId { get; set; }
        public string Statement { get; set; }
        public string Scope { get; set; }
        public string Status { get; set; }
        public string CreatedUtc { get; set; }
        public string Fingerprint { get; set; }
        public override string ToString(){return (Status??"CANDIDATE")+"   ·   "+(Statement??Id)+"   ·   scope "+(Scope??"UNSPECIFIED")+"   ·   pattern "+CivilizationalSynthesisKernel.Short(PatternId);}
    }
    internal sealed class SynthesisNote
    {
        public string Id { get; set; }
        public string SubjectId { get; set; }
        public string Text { get; set; }
        public string CreatedUtc { get; set; }
        public override string ToString(){return (SubjectId??"SYNTHΩ")+"   ·   "+(Text??"");}
    }
    internal sealed class SynthesisTransferTrial
    {
        public string Id { get; set; }
        public string PatternId { get; set; }
        public string TargetMissionId { get; set; }
        public string Question { get; set; }
        public string Status { get; set; }
        public string CreatedUtc { get; set; }
        public override string ToString(){return (Status??"PROPOSED")+"   ·   "+(Question??Id)+"   ·   target "+(TargetMissionId??"NEW")+"   ·   pattern "+CivilizationalSynthesisKernel.Short(PatternId);}
    }
    internal sealed class SynthesisBaseline
    {
        public string Id { get; set; }
        public string SnapshotFingerprint { get; set; }
        public int Patterns { get; set; }
        public int Transfers { get; set; }
        public int Missions { get; set; }
        public string CreatedUtc { get; set; }
        public override string ToString(){return (CreatedUtc??"")+"   ·   patterns "+Patterns+"   ·   transfers "+Transfers+"   ·   missions "+Missions+"   ·   "+CivilizationalSynthesisKernel.Short(SnapshotFingerprint);}
    }
    internal sealed class SynthesisSeal
    {
        public string Id { get; set; }
        public string SnapshotFingerprint { get; set; }
        public int Patterns { get; set; }
        public int TheoremCandidates { get; set; }
        public string CreatedUtc { get; set; }
        public string CertificateHash { get; set; }
        public override string ToString(){return "SYNTHESIS SEAL   ·   patterns "+Patterns+"   ·   theorem candidates "+TheoremCandidates+"   ·   "+CivilizationalSynthesisKernel.Short(SnapshotFingerprint);}
    }
    internal sealed class SynthesisStore
    {
        public int Schema { get; set; }
        public List<SynthesisTheoremCandidate> Theorems { get; set; }
        public List<SynthesisNote> Notes { get; set; }
        public List<SynthesisTransferTrial> Trials { get; set; }
        public List<SynthesisBaseline> Baselines { get; set; }
        public List<SynthesisSeal> Seals { get; set; }
        public SynthesisStore(){Schema=1;Theorems=new List<SynthesisTheoremCandidate>();Notes=new List<SynthesisNote>();Trials=new List<SynthesisTransferTrial>();Baselines=new List<SynthesisBaseline>();Seals=new List<SynthesisSeal>();}
    }

