        private static string StatePath(DeepSystemsContext ctx){Directory.CreateDirectory(ctx.StateRoot);return Path.Combine(ctx.StateRoot,"controller-civilizational-synthesis.json");}
        private static string LedgerPath(DeepSystemsContext ctx){Directory.CreateDirectory(ctx.StateRoot);return Path.Combine(ctx.StateRoot,"controller-civilizational-synthesis-ledger.jsonl");}
        private static string ExpeditionPath(DeepSystemsContext ctx){Directory.CreateDirectory(ctx.StateRoot);return Path.Combine(ctx.StateRoot,"controller-grand-unified-expedition.json");}
        private static void Load(DeepSystemsContext ctx){Store=new SynthesisStore();string p=StatePath(ctx);if(File.Exists(p))try{SynthesisStore x=ctx.Json.Deserialize<SynthesisStore>(File.ReadAllText(p,Encoding.UTF8));if(x!=null)Store=x;}catch{try{File.Copy(p,p+".corrupt-"+DateTime.UtcNow.ToString("yyyyMMddHHmmss",CultureInfo.InvariantCulture),true);}catch{}}if(Store.Theorems==null)Store.Theorems=new List<SynthesisTheoremCandidate>();if(Store.Notes==null)Store.Notes=new List<SynthesisNote>();if(Store.Trials==null)Store.Trials=new List<SynthesisTransferTrial>();if(Store.Baselines==null)Store.Baselines=new List<SynthesisBaseline>();if(Store.Seals==null)Store.Seals=new List<SynthesisSeal>();}
        private static void Save(DeepSystemsContext ctx){string p=StatePath(ctx),next=p+".next",prev=p+".previous";File.WriteAllText(next,ctx.Json.Serialize(Store),new UTF8Encoding(false));if(File.Exists(p))File.Copy(p,prev,true);if(File.Exists(p))File.Delete(p);File.Move(next,p);}
        private static void RefreshSnapshot(DeepSystemsContext ctx){string p=ExpeditionPath(ctx);ExpeditionCommandStore ex=new ExpeditionCommandStore();string raw="";if(File.Exists(p)){try{raw=File.ReadAllText(p,Encoding.UTF8);ExpeditionCommandStore z=ctx.Json.Deserialize<ExpeditionCommandStore>(raw);if(z!=null)ex=z;}catch{raw="CORRUPT";}}string fp=CivilizationalSynthesisKernel.HashText(raw);if(Snapshot==null||!Eq(fp,LoadedExpeditionFingerprint)){ConstellationSnapshot meta=KnowledgeConstellationKernel.Build(ex.Missions,fp);Snapshot=CivilizationalSynthesisKernel.Build(meta,ex.Missions,fp);LoadedExpeditionFingerprint=fp;}}
        private static void AppendLedger(DeepSystemsContext ctx,string kind,string subject){string p=LedgerPath(ctx);string prev="GENESIS";if(File.Exists(p)){string[] lines=File.ReadAllLines(p,Encoding.UTF8);if(lines.Length>0){string last=lines[lines.Length-1];int i=last.IndexOf("\"hash\":\"");if(i>=0){int a=i+8,b=last.IndexOf('"',a);if(b>a)prev=last.Substring(a,b-a);}}}string ts=DateTime.UtcNow.ToString("o",CultureInfo.InvariantCulture);string hash=CivilizationalSynthesisKernel.HashText(prev+"|"+ts+"|"+kind+"|"+(subject??""));string json="{\"utc\":\""+ts+"\",\"kind\":\""+Esc(kind)+"\",\"subject\":\""+Esc(subject)+"\",\"previous\":\""+prev+"\",\"hash\":\""+hash+"\"}";File.AppendAllText(p,json+Environment.NewLine,new UTF8Encoding(false));}
        private static string Esc(string s){return (s??"").Replace("\\","\\\\").Replace("\"","\\\"").Replace("\r"," ").Replace("\n"," ");}
        private static void Kinds(Window w,DeepSystemsContext ctx,string title,string kind){RefreshSnapshot(ctx);OpenCollection(w,title,Snapshot.Patterns.Where(x=>Eq(x.Kind,kind)).Cast<object>().ToList(),"Automatically mined; heuristic status retained.");}
        private static void TransferBand(Window w,DeepSystemsContext ctx,string title,double lo,double hi){RefreshSnapshot(ctx);OpenCollection(w,title,Snapshot.TransferProbes.Where(x=>x.Risk>=lo&&x.Risk<hi).Cast<object>().ToList(),"Target-specific risk combines pattern fragility, missing preconditions and context overlap.");}
        private static void ShowFamilies(Window w,DeepSystemsContext ctx){RefreshSnapshot(ctx);OpenCollection(w,"PATTERN FAMILIES",Snapshot.Patterns.GroupBy(x=>x.Kind??"UNKNOWN",StringComparer.OrdinalIgnoreCase).OrderByDescending(g=>g.Count()).Select(g=>(object)(g.Count().ToString("0000",CultureInfo.InvariantCulture)+"   ·   "+g.Key+"   ·   mean stability "+g.Average(x=>x.Stability).ToString("0.000",CultureInfo.InvariantCulture))).ToList(),"Family counts are descriptive.");}
        private static void ShowTokens(Window w,DeepSystemsContext ctx){RefreshSnapshot(ctx);OpenCollection(w,"CONCEPT MOTIF INDEX",Snapshot.Patterns.SelectMany(p=>p.Tokens.Select(t=>new{T=t,P=p.Id})).GroupBy(x=>x.T,StringComparer.OrdinalIgnoreCase).OrderByDescending(g=>g.Count()).Select(g=>(object)(g.Count().ToString("0000",CultureInfo.InvariantCulture)+" patterns   ·   "+g.Key)).ToList(),"Token index is lexical structure only.");}
        private static void ShowPreconditions(Window w,DeepSystemsContext ctx){RefreshSnapshot(ctx);OpenCollection(w,"PRECONDITION MATRIX",Snapshot.Patterns.SelectMany(p=>p.Preconditions.Select(c=>(object)(c+"   ·   "+p.Kind+"   ·   "+p.Label+"   ·   "+p.Id))).ToList(),"Preconditions are supporting civilization contexts, not proven necessary conditions.");}
        private static void ShowCivilizationIndex(Window w,DeepSystemsContext ctx){RefreshSnapshot(ctx);OpenCollection(w,"CIVILIZATION PRECONDITION INDEX",Snapshot.Patterns.SelectMany(p=>p.Preconditions).GroupBy(x=>x,StringComparer.OrdinalIgnoreCase).OrderByDescending(g=>g.Count()).Select(g=>(object)(g.Count().ToString("0000",CultureInfo.InvariantCulture)+" patterns   ·   "+g.Key)).ToList(),"Frequency says where support was observed, not where the pattern must hold.");}
        private static void ShowPatternMission(Window w,DeepSystemsContext ctx){RefreshSnapshot(ctx);OpenCollection(w,"PATTERN→MISSION MATRIX",Snapshot.Patterns.SelectMany(p=>p.MissionIds.Select(m=>(object)(p.Id+"   →   "+m+"   ·   "+p.Kind+"   ·   "+p.Label))).ToList(),"Recorded support relation from mined findings.");}
        private static void ShowPatternSource(Window w,DeepSystemsContext ctx){RefreshSnapshot(ctx);OpenCollection(w,"PATTERN→SOURCE MATRIX",Snapshot.Patterns.SelectMany(p=>p.SourceFingerprints.Select(s=>(object)(p.Id+"   →   "+s+"   ·   "+p.Label))).ToList(),"Exact retained source fingerprints only.");}
        private static void ShowPatternCounterexamples(Window w,DeepSystemsContext ctx){RefreshSnapshot(ctx);OpenCollection(w,"PATTERN→COUNTEREXAMPLE MATRIX",Snapshot.Patterns.SelectMany(p=>p.CounterexampleMissionIds.Select(m=>(object)(p.Id+"   ×   "+m+"   ·   "+p.Label))).ToList(),"Counterexample association comes from explicit unresolved contradiction participation.");}
        private static void Promote(Window w,DeepSystemsContext ctx){RefreshSnapshot(ctx);SynthesisPattern p=Choose(w,"SELECT PATTERN",Snapshot.Patterns);if(p==null)return;string statement=Prompt(w,"THEOREM CANDIDATE","Write the candidate statement. It remains explicitly unproven.",p.Description);if(String.IsNullOrWhiteSpace(statement))return;string scope=Prompt(w,"SCOPE","State where this candidate is intended to apply and where it is not.",String.Join(", ",p.Preconditions));SynthesisTheoremCandidate t=new SynthesisTheoremCandidate{Id="THM-"+Guid.NewGuid().ToString("N").Substring(0,16).ToUpperInvariant(),PatternId=p.Id,Statement=statement.Trim(),Scope=(scope??"").Trim(),Status="CANDIDATE",CreatedUtc=DateTime.UtcNow.ToString("o",CultureInfo.InvariantCulture)};t.Fingerprint=CivilizationalSynthesisKernel.HashText(t.Id+"|"+t.PatternId+"|"+t.Statement+"|"+t.Scope+"|"+p.Fingerprint);Store.Theorems.Insert(0,t);Save(ctx);AppendLedger(ctx,"THEOREM_CANDIDATE",t.Id);}
        private static void ShowTheoremProvenance(Window w,DeepSystemsContext ctx){RefreshSnapshot(ctx);Dictionary<string,SynthesisPattern> p=Snapshot.Patterns.ToDictionary(x=>x.Id,StringComparer.OrdinalIgnoreCase);List<object> rows=new List<object>();foreach(SynthesisTheoremCandidate t in Store.Theorems){SynthesisPattern x;rows.Add((object)(t.Id+"   →   "+t.PatternId+"   ·   "+(p.TryGetValue(t.PatternId,out x)?("missions "+x.SupportMissions+" sources "+x.UniqueSources+" counterexamples "+x.CounterexampleMissionIds.Count):"PATTERN NO LONGER IN CURRENT SNAPSHOT")));}OpenCollection(w,"THEOREM PROVENANCE",rows,"A promoted candidate never sheds its originating pattern identity.");}
        private static void AddNote(Window w,DeepSystemsContext ctx){string subject=Prompt(w,"NOTE SUBJECT","Pattern/theorem/transfer id, or SYNTHΩ for a global note.","SYNTHΩ");if(String.IsNullOrWhiteSpace(subject))return;string text=Prompt(w,"NOTE","Interpretation, caveat, objection, transfer idea or follow-up.","");if(String.IsNullOrWhiteSpace(text))return;SynthesisNote n=new SynthesisNote{Id="NOTE-"+Guid.NewGuid().ToString("N").Substring(0,12).ToUpperInvariant(),SubjectId=subject.Trim(),Text=text.Trim(),CreatedUtc=DateTime.UtcNow.ToString("o",CultureInfo.InvariantCulture)};Store.Notes.Insert(0,n);Save(ctx);AppendLedger(ctx,"NOTE",n.Id);}
        private static void LaunchTransfer(Window w,DeepSystemsContext ctx){RefreshSnapshot(ctx);SynthesisPattern p=Choose(w,"SELECT PATTERN TO TEST",Snapshot.Patterns);if(p==null)return;string q="Under what explicit conditions does the candidate pattern '"+p.Label+"' transfer, fail, or require revision in a new context?";SynthesisTransferTrial t=new SynthesisTransferTrial{Id="TRIAL-"+Guid.NewGuid().ToString("N").Substring(0,16).ToUpperInvariant(),PatternId=p.Id,Question=q,Status="STARTED",CreatedUtc=DateTime.UtcNow.ToString("o",CultureInfo.InvariantCulture)};Store.Trials.Insert(0,t);Save(ctx);AppendLedger(ctx,"TRANSFER_TRIAL",t.Id);GrandUnifiedExpeditionCommand.OpenFromSynthesisPattern(w,ctx,q,"SYNTHΩ:"+p.Id,p.Fingerprint);}
        private static void Query(Window w,DeepSystemsContext ctx){RefreshSnapshot(ctx);string q=Prompt(w,"PATTERN QUERY","Search kind, label, description, basis or tokens.","");if(String.IsNullOrWhiteSpace(q))return;OpenCollection(w,"QUERY · "+q,Snapshot.Patterns.Where(p=>Contains(p.Kind,q)||Contains(p.Label,q)||Contains(p.Description,q)||Contains(p.Basis,q)||p.Tokens.Any(t=>Contains(t,q))).Cast<object>().ToList(),"Lexical local query over the current synthesis snapshot.");}
        private static void CreateBaseline(Window w,DeepSystemsContext ctx){RefreshSnapshot(ctx);SynthesisBaseline b=new SynthesisBaseline{Id="BASE-"+Guid.NewGuid().ToString("N").Substring(0,16).ToUpperInvariant(),SnapshotFingerprint=Snapshot.Fingerprint,Patterns=Snapshot.Patterns.Count,Transfers=Snapshot.TransferProbes.Count,Missions=Snapshot.Missions,CreatedUtc=DateTime.UtcNow.ToString("o",CultureInfo.InvariantCulture)};Store.Baselines.Insert(0,b);Save(ctx);AppendLedger(ctx,"BASELINE",b.Id);}
        private static void Drift(Window w,DeepSystemsContext ctx){RefreshSnapshot(ctx);SynthesisBaseline b=Choose(w,"SELECT BASELINE",Store.Baselines);if(b==null)return;StringBuilder s=new StringBuilder();s.AppendLine("SYNTHΩ PATTERN DRIFT");s.AppendLine(new string('=',70));s.AppendLine("baseline fingerprint: "+b.SnapshotFingerprint);s.AppendLine("current fingerprint:  "+Snapshot.Fingerprint);s.AppendLine("identity changed:     "+(!Eq(b.SnapshotFingerprint,Snapshot.Fingerprint)));s.AppendLine("patterns:             "+b.Patterns+" → "+Snapshot.Patterns.Count+"   Δ "+(Snapshot.Patterns.Count-b.Patterns));s.AppendLine("transfers:            "+b.Transfers+" → "+Snapshot.TransferProbes.Count+"   Δ "+(Snapshot.TransferProbes.Count-b.Transfers));s.AppendLine("missions:             "+b.Missions+" → "+Snapshot.Missions+"   Δ "+(Snapshot.Missions-b.Missions));s.AppendLine();s.AppendLine("Drift records structural change. It does not infer why meaning changed.");TextView(w,"PATTERN DRIFT RADAR",s.ToString());}
        private static void Seal(Window w,DeepSystemsContext ctx){RefreshSnapshot(ctx);List<SynthesisValidationFinding> v=CivilizationalSynthesisKernel.Validate(Snapshot);if(v.Any(x=>Eq(x.Severity,"ERROR"))){OpenCollection(w,"SEAL REFUSED",v.Cast<object>().ToList(),"Structural errors must be repaired before sealing.");return;}SynthesisSeal s=new SynthesisSeal{Id="SEAL-"+Guid.NewGuid().ToString("N").Substring(0,16).ToUpperInvariant(),SnapshotFingerprint=Snapshot.Fingerprint,Patterns=Snapshot.Patterns.Count,TheoremCandidates=Store.Theorems.Count,CreatedUtc=DateTime.UtcNow.ToString("o",CultureInfo.InvariantCulture)};s.CertificateHash=CivilizationalSynthesisKernel.HashText(s.Id+"|"+s.SnapshotFingerprint+"|"+s.Patterns+"|"+s.TheoremCandidates+"|"+s.CreatedUtc);Store.Seals.Insert(0,s);Save(ctx);AppendLedger(ctx,"SEAL",s.Id);}
        private static void ShowLedger(Window w,DeepSystemsContext ctx){string p=LedgerPath(ctx);List<object> rows=File.Exists(p)?File.ReadAllLines(p,Encoding.UTF8).Reverse().Cast<object>().ToList():new List<object>();OpenCollection(w,"SYNTHΩ LEDGER",rows,"Local activity chain. EXPΩ and METAΩ retain their own authority ledgers.");}
        private static void Export(Window w,DeepSystemsContext ctx){RefreshSnapshot(ctx);string dir=Path.Combine(ctx.DataRoot,"exports","civilizational-synthesis");Directory.CreateDirectory(dir);string stamp=DateTime.UtcNow.ToString("yyyyMMdd-HHmmss",CultureInfo.InvariantCulture);string root=Path.Combine(dir,"synth-omega-"+stamp);File.WriteAllText(root+".snapshot.json",ctx.Json.Serialize(Snapshot),new UTF8Encoding(false));File.WriteAllText(root+".review.json",ctx.Json.Serialize(Store),new UTF8Encoding(false));StringBuilder md=new StringBuilder();md.AppendLine("# SYNTHΩ Civilizational Synthesis");md.AppendLine();md.AppendLine("Snapshot fingerprint: `"+Snapshot.Fingerprint+"`");md.AppendLine();md.AppendLine("Patterns: "+Snapshot.Patterns.Count+"  ");md.AppendLine("Transfer probes: "+Snapshot.TransferProbes.Count+"  ");md.AppendLine("Theorem candidates: "+Store.Theorems.Count+"  ");md.AppendLine();md.AppendLine("## Highest-stability candidates");foreach(SynthesisPattern p in Snapshot.Patterns.Take(30))md.AppendLine("- "+p.ToString());File.WriteAllText(root+".md",md.ToString(),new UTF8Encoding(false));AppendLedger(ctx,"EXPORT",root);TextView(w,"EXPORT COMPLETE",root+Environment.NewLine+Snapshot.Fingerprint);}
        private static void Autopsy(Window w,DeepSystemsContext ctx){RefreshSnapshot(ctx);StringBuilder b=new StringBuilder();b.AppendLine("SYNTHΩ CIVILIZATIONAL SYNTHESIS AUTOPSY");b.AppendLine(new string('=',76));b.AppendLine("missions:                 "+Snapshot.Missions);b.AppendLine("findings:                 "+Snapshot.Findings);b.AppendLine("unique sources:           "+Snapshot.UniqueSources);b.AppendLine("open contradictions:      "+Snapshot.OpenContradictions);b.AppendLine("patterns:                 "+Snapshot.Patterns.Count);b.AppendLine("invariant candidates:     "+Snapshot.Patterns.Count(x=>Eq(x.Kind,"INVARIANT_CANDIDATE")));b.AppendLine("failure signatures:       "+Snapshot.Patterns.Count(x=>Eq(x.Kind,"FAILURE_SIGNATURE")));b.AppendLine("anti-pattern candidates:  "+Snapshot.Patterns.Count(x=>Eq(x.Kind,"ANTI_PATTERN_CANDIDATE")));b.AppendLine("patterns w/counterexample:"+Snapshot.Patterns.Count(x=>x.CounterexampleMissionIds.Count>0));b.AppendLine("transfer probes:          "+Snapshot.TransferProbes.Count);b.AppendLine("theorem candidates:       "+Store.Theorems.Count);b.AppendLine("transfer trials:          "+Store.Trials.Count);b.AppendLine("validation errors:        "+CivilizationalSynthesisKernel.Validate(Snapshot).Count(x=>Eq(x.Severity,"ERROR")));b.AppendLine("snapshot fp:              "+Snapshot.Fingerprint);b.AppendLine();b.AppendLine("Authority boundary: automatic recurrence is heuristic; theorem candidates are human-promoted hypotheses; transfer remains untested until an expedition gathers evidence.");TextView(w,"SYNTHESIS AUTOPSY",b.ToString());}
        private static T Choose<T>(Window owner,string title,IList<T> items) where T:class{if(items==null||items.Count==0)return null;Window w=W(owner,"YOMI · "+title,1120,760);DockPanel root=Shell(title,"Double-click to select.");ListBox list=List();list.ItemsSource=items;T selected=null;list.MouseDoubleClick+=delegate{selected=list.SelectedItem as T;w.DialogResult=selected!=null;w.Close();};root.Children.Add(list);w.Content=root;bool? r=w.ShowDialog();return r==true?selected:null;}
        private static Window W(Window owner,string title,double width,double height){return new Window{Title=title,Width=width,Height=height,Background=Bg,Foreground=Text,WindowStartupLocation=owner==null?WindowStartupLocation.CenterScreen:WindowStartupLocation.CenterOwner,Owner=owner};}
        private static DockPanel Shell(string title,string subtitle){DockPanel root=new DockPanel{Background=Bg};StackPanel head=new StackPanel{Margin=new Thickness(20,18,20,10)};head.Children.Add(new TextBlock{Text=title,Foreground=Text,FontSize=25,FontWeight=FontWeights.Bold});head.Children.Add(new TextBlock{Text=subtitle??"",Foreground=Muted,FontSize=13,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,5,0,0)});DockPanel.SetDock(head,Dock.Top);root.Children.Add(head);return root;}
        private static void Portal(WrapPanel panel,string badge,string title,string detail,RoutedEventHandler click){Button b=new Button{Width=285,MinHeight=118,Margin=new Thickness(7),Padding=new Thickness(14),Background=Surface,Foreground=Text,BorderBrush=Border,BorderThickness=new Thickness(1),HorizontalContentAlignment=HorizontalAlignment.Stretch};StackPanel p=new StackPanel();p.Children.Add(new TextBlock{Text=badge+"   "+title,Foreground=Accent,FontWeight=FontWeights.Bold,FontSize=13,TextWrapping=TextWrapping.Wrap});p.Children.Add(new TextBlock{Text=detail,Foreground=Muted,FontSize=12,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,7,0,0)});b.Content=p;b.Click+=click;panel.Children.Add(b);}
        private static ListBox List(){return new ListBox{Margin=new Thickness(18),Background=Surface,Foreground=Text,BorderBrush=Border,BorderThickness=new Thickness(1),FontFamily=new FontFamily("Consolas"),FontSize=12};}
        private static void OpenCollection(Window owner,string title,IList<object> items,string note){Window w=W(owner,"YOMI · "+title,1380,850);DockPanel root=Shell(title,note+"   ·   "+(items==null?0:items.Count)+" rows");ListBox list=List();list.ItemsSource=items??new List<object>();root.Children.Add(list);w.Content=root;w.Show();}
        private static void TextView(Window owner,string title,string text){Window w=W(owner,"YOMI · "+title,1380,880);DockPanel root=Shell(title,"Read-only representation.");TextBox box=new TextBox{Text=text??"",Margin=new Thickness(18),Background=Surface,Foreground=Text,BorderBrush=Border,FontFamily=new FontFamily("Consolas"),FontSize=13,IsReadOnly=true,AcceptsReturn=true,AcceptsTab=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Auto};root.Children.Add(box);w.Content=root;w.Show();}
        private static string Prompt(Window owner,string title,string label,string initial){Window w=W(owner,"YOMI · "+title,820,340);DockPanel root=Shell(title,label);TextBox box=new TextBox{Text=initial??"",Margin=new Thickness(20,6,20,10),Padding=new Thickness(8),Background=Surface,Foreground=Text,BorderBrush=Border,AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,MinHeight=100,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};DockPanel.SetDock(box,Dock.Top);root.Children.Add(box);StackPanel buttons=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(20)};Button ok=new Button{Content="COMMIT",Padding=new Thickness(18,7,18,7),Margin=new Thickness(6),Background=Raised,Foreground=Green,BorderBrush=Border};Button cancel=new Button{Content="CANCEL",Padding=new Thickness(18,7,18,7),Margin=new Thickness(6),Background=Raised,Foreground=Muted,BorderBrush=Border};string value=null;ok.Click+=delegate{value=box.Text;w.DialogResult=true;w.Close();};cancel.Click+=delegate{w.DialogResult=false;w.Close();};buttons.Children.Add(cancel);buttons.Children.Add(ok);root.Children.Add(buttons);w.Content=root;bool? r=w.ShowDialog();return r==true?value:null;}
        private static bool Eq(string a,string b){return String.Equals(a,b,StringComparison.OrdinalIgnoreCase);}private static bool Contains(string a,string b){return !String.IsNullOrWhiteSpace(a)&&!String.IsNullOrWhiteSpace(b)&&a.IndexOf(b,StringComparison.OrdinalIgnoreCase)>=0;}private static Brush B(string hex){return (Brush)new BrushConverter().ConvertFromString(hex);}
    }
}
